def run(c,root,args):
 c.group='library-allocation';pub=root/'labs/foundations/library_depth';private=root/'assessor/legacy_library';include=root/'labs/foundations/include';foundation=root/'assessor/foundations/foundation.c';source=private/'allocation.c'
