 for key,ordinary,changed in [('07.a','Nonzero count/width, multiplication and alignment rounding overflow fail before allocation; actual malloc/calloc/realloc/aligned_alloc execute','Actual alignas64 concrete array constructed and resized through allocate-copy-free; extended support is selected toolchain/libc evidence'),('07.b','Zero resize refuses before calling realloc-like callback; explicit release clears sole owner and repeated empty release has no effect','Original adverse callback returnsNULL for zero without freeing; adapter never delegates zero and retains a unique explicit cleanup path'),('07.c','ABCD survives injected first nonzero resize failure, then successful retry and exactly-one release','Fallible allocate-copy-free fails at every copied prefix0..4, releases staging and preserves original owner; retry, shrink and over-aligned relocation preserve admitted prefix')]:c.observe('T12.'+key,ordinary,['library-allocation']);c.observe('T12.'+key,changed,['library-allocation'],True)
